idata.python:
# volume
LEVEL = 1.0

# place drum hits
def hit(sound, time, volume):
    moveTo(time)
    playNote(sound, beats=0.18, velocity=int(volume * LEVEL))

# full song
for bar in range(36):
    start = bar * 4
    if 4 <= bar < 20 or 24 <= bar < 32:
        hit(2, start + 1.035, 85)
        hit(2, start + 3.035, 90)
        if bar % 2 == 1:
            hit(3, start + 2.78, 26)  # soft snare
        if bar % 4 == 3:
            hit(11, start + 3.05, 24)  # soft clap
    elif bar == 3:
        hit(3, start + 3.04, 37)
    elif bar in [32, 33]:
        hit(2, start + 3.035, 58)

    if bar in [11, 19, 31]:
        hit(3, start + 3.52, 39)
        hit(2, start + 3.78, 28)

# keep parts in time
moveTo(143.75)
rest(0.25)
